"""不可变的 ABI 类型对象。

类型对象分三种，可通过类区分：
- ElementaryType：基础类型（uintM/intM/address/bool/string/bytes/bytesM）
- ArrayType：数组类型（T[] 动态数组、T[n] 定长数组）
- TupleType：元组类型（(T1,T2,...)，允许空元组）

所有对象均为 frozen dataclass，构造时即完成自洽校验，包括
从基础类型向外最多 MAX_TYPE_DEPTH 层的嵌套上限。
"""

from __future__ import annotations

from dataclasses import dataclass, field

from ._exceptions import ABITypeError

#: 从基础类型向外计数的最大嵌套层数（基础类型自身计第 1 层）。
MAX_TYPE_DEPTH = 128

_UINT = "uint"
_INT = "int"
_ADDRESS = "address"
_BOOL = "bool"
_STRING = "string"
_BYTES = "bytes"


@dataclass(frozen=True)
class ABIType:
    """所有 ABI 类型对象的抽象基类。"""

    @property
    def depth(self) -> int:
        """从基础类型向外的层数，基础类型为 1。"""
        raise NotImplementedError


@dataclass(frozen=True)
class ElementaryType(ABIType):
    """基础类型。

    kind 取值：
    - ``"uint"`` / ``"int"``：bit_size 为 8..256 的 8 的倍数
    - ``"address"`` / ``"bool"`` / ``"string"``：两个宽度均为 None
    - ``"bytes"``：byte_size 为 None 表示动态 bytes，否则为 1..32
    """

    kind: str
    bit_size: int | None = None
    byte_size: int | None = None

    def __post_init__(self) -> None:
        kind = self.kind
        if kind in (_UINT, _INT):
            if not isinstance(self.bit_size, int) or isinstance(self.bit_size, bool):
                raise ABITypeError(f"{kind} 类型必须给出整数位宽")
            if self.byte_size is not None:
                raise ABITypeError(f"{kind} 类型不能带有字节宽度")
            if not (8 <= self.bit_size <= 256 and self.bit_size % 8 == 0):
                raise ABITypeError(
                    f"{kind} 的位宽必须是 8 到 256 之间 8 的倍数，得到 {self.bit_size}"
                )
        elif kind in (_ADDRESS, _BOOL, _STRING, _BYTES):
            if self.bit_size is not None:
                raise ABITypeError(f"{kind} 类型不能带有整数位宽")
            if kind == _BYTES and self.byte_size is not None:
                if (
                    isinstance(self.byte_size, bool)
                    or not isinstance(self.byte_size, int)
                    or not (1 <= self.byte_size <= 32)
                ):
                    raise ABITypeError(
                        f"bytesM 的 M 必须在 1 到 32 之间，得到 {self.byte_size!r}"
                    )
            elif self.byte_size is not None:
                raise ABITypeError(f"{kind} 类型不能带有字节宽度")
        else:
            raise ABITypeError(f"未知的基础类型：{kind!r}")

    @property
    def depth(self) -> int:
        return 1


@dataclass(frozen=True)
class ArrayType(ABIType):
    """数组类型；length 为 None 表示动态数组 T[]，否则为定长数组 T[n]。"""

    element_type: ABIType
    length: int | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.element_type, ABIType):
            raise ABITypeError("数组元素类型必须是 ABIType")
        if self.length is not None:
            if isinstance(self.length, bool) or not isinstance(self.length, int):
                raise ABITypeError(f"数组长度必须是正整数，得到 {self.length!r}")
            if self.length <= 0:
                raise ABITypeError(f"数组长度必须是正整数，得到 {self.length}")
        if self.depth > MAX_TYPE_DEPTH:
            raise ABITypeError(f"类型嵌套超过 {MAX_TYPE_DEPTH} 层")

    @property
    def depth(self) -> int:
        return self.element_type.depth + 1


@dataclass(frozen=True)
class TupleType(ABIType):
    """元组类型，components 按声明顺序保存各组成部分。

    names 为 None 表示未命名元组（默认）；否则它必须与 components 等长，
    每项为字段名字符串或 None（该位置未命名）。字段名仅用于路径寻址，
    不参与规范化（:func:`format_abi_type` 不输出名称）。
    """

    components: tuple[ABIType, ...] = field(default=())
    names: tuple[str | None, ...] | None = None

    def __post_init__(self) -> None:
        try:
            components = tuple(self.components)
        except TypeError as exc:
            raise ABITypeError("元组组成部分必须是 ABIType 序列") from exc
        for component in components:
            if not isinstance(component, ABIType):
                raise ABITypeError("元组组成部分必须是 ABIType")
        object.__setattr__(self, "components", components)
        if self.names is not None:
            try:
                names = tuple(self.names)
            except TypeError as exc:
                raise ABITypeError("元组字段名必须是 str/None 序列") from exc
            if len(names) != len(components):
                raise ABITypeError(
                    f"字段名数量 {len(names)} 与元组组成部分数量 "
                    f"{len(components)} 不一致"
                )
            for name in names:
                if name is not None and not isinstance(name, str):
                    raise ABITypeError("元组字段名必须是 str 或 None")
            object.__setattr__(self, "names", names)
        if self.depth > MAX_TYPE_DEPTH:
            raise ABITypeError(f"类型嵌套超过 {MAX_TYPE_DEPTH} 层")

    @property
    def depth(self) -> int:
        return 1 + max((c.depth for c in self.components), default=0)

"""ABI 类型字符串的递归下降解析器。

语法（空白规则见下）::

    type       := elementary | tuple ，后接零个或多个数组后缀
    elementary := uintM | intM | address | bool | string | bytes | bytesM
    tuple      := '(' [type (',' type)*] ')'
    suffix     := '[]' | '[' [1-9][0-9]* ']'

空白（仅 ASCII 空白）只允许出现在：
1. 整个类型字符串的两端；
2. 元组中逗号的两侧。
其余位置的空白（类型词内部、括号内侧、数组语法内部等）一律报错。
输入必须完整解析，尾随任何非空白字符均报错。
"""

from __future__ import annotations

from ._exceptions import ABITypeError
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WHITESPACE = " \t\n\r\f\v"

#: 解析器括号递归的安全上限：语义嵌套上限（128 层）由类型对象构造时
#: 检查；此阈值仅用于在触及 Python 递归限制（实测约 500 层括号）前抛出
#: ABITypeError，远低于递归上限且高于任何合法输入。
_RECURSION_SAFETY_LIMIT = 200


class _Parser:
    def __init__(self, text: str) -> None:
        self._text = text
        self._pos = 0
        self._len = len(text)
        self._tuple_depth = 0

    def parse(self) -> ABIType:
        self._skip_whitespace()
        result = self._parse_type()
        self._skip_whitespace()
        if self._pos != self._len:
            raise self._error("存在无法解析的尾随内容")
        return result

    # ---- 通用构件 -------------------------------------------------------

    def _error(self, message: str) -> ABITypeError:
        return ABITypeError(f"无效的 ABI 类型 {self._text!r}（位置 {self._pos}）：{message}")

    def _skip_whitespace(self) -> None:
        text = self._text
        while self._pos < self._len and text[self._pos] in _WHITESPACE:
            self._pos += 1

    def _peek(self) -> str | None:
        if self._pos >= self._len:
            return None
        return self._text[self._pos]

    # ---- 类型 -----------------------------------------------------------

    def _parse_type(self) -> ABIType:
        ch = self._peek()
        if ch is None:
            raise self._error("类型不完整")
        if ch == "(":
            head: ABIType = self._parse_tuple()
        elif ch.isascii() and ch.isalpha():
            head = self._parse_elementary()
        else:
            raise self._error("此处应为基础类型或元组")
        return self._parse_suffixes(head)

    def _parse_elementary(self) -> ElementaryType:
        text = self._text
        start = self._pos
        while self._pos < self._len:
            ch = text[self._pos]
            if ch.isascii() and ch.isalnum():
                self._pos += 1
            else:
                break
        word = text[start:self._pos]
        return self._classify(word)

    def _classify(self, word: str) -> ElementaryType:
        if word in ("address", "bool", "string"):
            return ElementaryType(word)
        if word == "bytes":
            return ElementaryType("bytes")
        if word.startswith("bytes") and len(word) > len("bytes"):
            return self._sized_bytes(word)
        if word.startswith("uint") or word.startswith("int"):
            return self._sized_integer(word)
        raise self._error(f"不是合法的基础类型：{word!r}")

    def _digits_suffix(self, word: str, prefix: str) -> str:
        digits = word[len(prefix):]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise self._error(f"不是合法的基础类型：{word!r}")
        if len(digits) > 1 and digits[0] == "0":
            raise self._error(f"类型宽度不允许前导零：{word!r}")
        return digits

    def _sized_integer(self, word: str) -> ElementaryType:
        if word.startswith("uint"):
            prefix, kind = "uint", "uint"
        else:
            prefix, kind = "int", "int"
        digits = self._digits_suffix(word, prefix)
        try:
            return ElementaryType(kind, bit_size=int(digits))
        except ABITypeError:
            # 规范化错误信息：重新抛出由本解析器生成的错误
            raise self._error(
                f"{kind} 的位宽必须是 8 到 256 之间 8 的倍数，得到 {digits}"
            ) from None

    def _sized_bytes(self, word: str) -> ElementaryType:
        digits = self._digits_suffix(word, "bytes")
        try:
            return ElementaryType("bytes", byte_size=int(digits))
        except ABITypeError:
            raise self._error(f"bytesM 的 M 必须在 1 到 32 之间，得到 {digits}") from None

    def _parse_tuple(self) -> TupleType:
        # 调用前当前字符为 '('；括号内侧不允许空白。
        self._pos += 1
        self._tuple_depth += 1
        # 语义嵌套上限由类型对象构造检查；此处仅在触及 Python 递归限制
        # 前拦截过深（或大量未闭合）的括号，保证唯一异常约定。
        if self._tuple_depth > _RECURSION_SAFETY_LIMIT:
            self._tuple_depth -= 1
            raise self._error("类型嵌套过深或括号未正确闭合")
        try:
            if self._peek() == ")":
                self._pos += 1
                return TupleType(())
            components: list[ABIType] = []
            while True:
                components.append(self._parse_type())
                # 逗号左侧允许 ASCII 空白；但 ')' 内侧不允许，因此先记录
                # 是否跳过了空白，若空白后直接是 ')' 则属非法。
                anchor = self._pos
                self._skip_whitespace()
                had_whitespace = self._pos != anchor
                ch = self._peek()
                if ch == ",":
                    self._pos += 1
                    # 逗号右侧允许 ASCII 空白。
                    self._skip_whitespace()
                    if self._peek() in (None, ",", ")"):
                        raise self._error("逗号后缺少类型")
                    continue
                if ch == ")":
                    if had_whitespace:
                        raise self._error("元组 ')' 内侧不允许空白")
                    self._pos += 1
                    return TupleType(tuple(components))
                raise self._error("元组中应为 ',' 或 ')'")
        finally:
            self._tuple_depth -= 1

    def _parse_suffixes(self, head: ABIType) -> ABIType:
        current = head
        while self._peek() == "[":
            self._pos += 1
            ch = self._peek()
            if ch is None:
                raise self._error("数组后缀不完整")
            if ch == "]":
                self._pos += 1
                current = ArrayType(current)
                continue
            # 定长数组：只接受 [1-9][0-9]*，拒绝 0 与前导零。
            if not (ch.isascii() and ch.isdigit()) or ch == "0":
                raise self._error("数组长度必须是无前导零的正整数")
            start = self._pos
            while True:
                ch = self._peek()
                if ch is not None and ch.isascii() and ch.isdigit():
                    self._pos += 1
                    continue
                break
            length = int(self._text[start:self._pos])
            if self._peek() != "]":
                raise self._error("数组后缀缺少 ']'")
            self._pos += 1
            current = ArrayType(current, length)
        return current


def parse_abi_type(type_string: str) -> ABIType:
    """解析 ABI 类型字符串，返回不可变类型对象。

    无效输入统一抛出 :class:`abi_kit.ABITypeError`。
    """
    if not isinstance(type_string, str):
        raise ABITypeError(f"ABI 类型必须是字符串，得到 {type(type_string).__name__}")
    if type_string == "":
        raise ABITypeError("无效的 ABI 类型 ''：类型为空")
    return _Parser(type_string).parse()

"""Solidity ABI 值层编解码。

遵循 Solidity ABI 的 head/tail 布局：

- 静态类型直接占用一个或多个 32 字节字；
- 动态类型（string / 动态 bytes / 动态数组 / 含动态成员的定长数组
  或元组）在 head 中放 32 字节偏移，实体置于 tail；
- 动态数组实体以长度字开头，随后是与“等长定长数组”相同的块；
- 偏移均相对于所属块（数组元素块的起点在长度字之后）。

解码采用严格规范：块内动态成员必须按声明顺序紧密排列（偏移恰好指向前
一动态实体的终点），不允许空洞、重叠或倒序；所有填充字节必须为零。

值口径：
- uintM/intM -> int，bool -> bool，string -> str；
- bytes/bytesM -> bytes；
- address -> 小写 ``"0x" + 40 个十六进制字符``；
- 数组 -> list，元组 -> tuple。

所有值不匹配、非法编码与不适用的类型对象统一抛出
:class:`abi_kit.ABIValueError`；类型层错误仍属
:class:`abi_kit.ABITypeError`，本模块不改变其适用范围。
"""

from __future__ import annotations

from ._exceptions import ABIValueError
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WORD = 32


# ---- 类型静态性质 --------------------------------------------------------


def _is_dynamic(abi_type: ABIType) -> bool:
    if isinstance(abi_type, ElementaryType):
        return abi_type.kind == "string" or (
            abi_type.kind == "bytes" and abi_type.byte_size is None
        )
    if isinstance(abi_type, ArrayType):
        return abi_type.length is None or _is_dynamic(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return any(_is_dynamic(c) for c in abi_type.components)
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _static_size(abi_type: ABIType) -> int:
    """静态类型作为一个整体占用的字节数（仅对非动态类型调用）。"""
    if isinstance(abi_type, ElementaryType):
        return _WORD
    if isinstance(abi_type, ArrayType):
        return abi_type.length * _static_size(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return sum(_static_size(c) for c in abi_type.components)
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _head_slot(abi_type: ABIType) -> int:
    """该类型作为块成员时在 head 中占用的字节数。"""
    return _WORD if _is_dynamic(abi_type) else _static_size(abi_type)


# ---- 编码 ----------------------------------------------------------------


def _uint_word(value: int) -> bytes:
    return value.to_bytes(_WORD, "big", signed=False)


def _address_bytes(value) -> bytes:
    if not isinstance(value, str):
        raise ABIValueError(f"address 需要十六进制字符串，得到 {type(value).__name__}")
    text = value[2:] if value.startswith(("0x", "0X")) else value
    if len(text) != 40 or any(c not in "0123456789abcdefABCDEF" for c in text):
        raise ABIValueError(
            f"address 必须是带或不带 0x 前缀的 40 位十六进制字符串：{value!r}"
        )
    return bytes.fromhex(text)


def _len_prefixed(payload: bytes) -> bytes:
    padding = (-len(payload)) % _WORD
    return _uint_word(len(payload)) + payload + b"\x00" * padding


def _encode_elementary(t: ElementaryType, value) -> bytes:
    kind = t.kind
    if kind == "uint":
        if isinstance(value, bool) or not isinstance(value, int):
            raise ABIValueError(
                f"uint{t.bit_size} 需要 int，得到 {type(value).__name__}"
            )
        bits = t.bit_size
        if not 0 <= value < 1 << bits:
            raise ABIValueError(f"uint{bits} 超出范围 [0, {2**bits - 1}]：{value}")
        return _uint_word(value)
    if kind == "int":
        if isinstance(value, bool) or not isinstance(value, int):
            raise ABIValueError(
                f"int{t.bit_size} 需要 int，得到 {type(value).__name__}"
            )
        bits = t.bit_size
        low = -(1 << (bits - 1))
        high = (1 << (bits - 1)) - 1
        if not low <= value <= high:
            raise ABIValueError(f"int{bits} 超出补码范围 [{low}, {high}]：{value}")
        return value.to_bytes(_WORD, "big", signed=True)
    if kind == "address":
        return b"\x00" * 12 + _address_bytes(value)
    if kind == "bool":
        if not isinstance(value, bool):
            raise ABIValueError(f"bool 需要 Python bool，得到 {type(value).__name__}")
        return _uint_word(1 if value else 0)
    if kind == "string":
        if not isinstance(value, str):
            raise ABIValueError(f"string 需要 str，得到 {type(value).__name__}")
        try:
            payload = value.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ABIValueError(f"字符串无法编码为 UTF-8：{exc}") from exc
        return _len_prefixed(payload)
    # bytes（动态）或 bytesM
    if not isinstance(value, bytes):
        label = "bytes" if t.byte_size is None else f"bytes{t.byte_size}"
        raise ABIValueError(f"{label} 需要 bytes，得到 {type(value).__name__}")
    if t.byte_size is None:
        return _len_prefixed(value)
    if len(value) != t.byte_size:
        raise ABIValueError(
            f"bytes{t.byte_size} 需要恰好 {t.byte_size} 字节，得到 {len(value)} 字节"
        )
    return value + b"\x00" * (_WORD - t.byte_size)


def _encode_block(member_types: list[ABIType], values: list) -> bytes:
    """编码一个 head/tail 块（元组成员或一组同构数组元素）。

    动态成员在 head 中的偏移相对于本块起点，动态实体按声明顺序紧密
    拼接在整块 head 之后。
    """
    head_chunks: list[bytes] = []
    dynamic_entities: list[tuple[int, bytes]] = []
    head_length = 0
    for index, (member_type, value) in enumerate(zip(member_types, values)):
        if _is_dynamic(member_type):
            head_chunks.append(b"\x00" * _WORD)
            dynamic_entities.append((index, _encode(member_type, value)))
        else:
            head_chunks.append(_encode(member_type, value))
        head_length += _head_slot(member_type)

    tail = bytearray()
    for index, entity in dynamic_entities:
        head_chunks[index] = _uint_word(head_length + len(tail))
        tail += entity
    return b"".join(head_chunks) + bytes(tail)


def _encode(abi_type: ABIType, value) -> bytes:
    """把值编码为一个自洽实体（动态类型即其 tail 实体）。"""
    if isinstance(abi_type, ElementaryType):
        return _encode_elementary(abi_type, value)
    if isinstance(abi_type, ArrayType):
        if not isinstance(value, list):
            raise ABIValueError(f"数组需要 list，得到 {type(value).__name__}")
        element_type = abi_type.element_type
        if abi_type.length is not None and len(value) != abi_type.length:
            raise ABIValueError(
                f"定长数组长度应为 {abi_type.length}，得到 {len(value)}"
            )
        block = _encode_block([element_type] * len(value), list(value))
        if abi_type.length is None:
            return _uint_word(len(value)) + block
        return block
    if isinstance(abi_type, TupleType):
        if not isinstance(value, tuple):
            raise ABIValueError(f"元组需要 tuple，得到 {type(value).__name__}")
        if len(value) != len(abi_type.components):
            raise ABIValueError(
                f"元组长度应为 {len(abi_type.components)}，得到 {len(value)}"
            )
        return _encode_block(list(abi_type.components), list(value))
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


# ---- 解码 ----------------------------------------------------------------


def _read_word(data: bytes, pos: int, bound: int) -> bytes:
    if pos < 0 or pos + _WORD > bound:
        raise ABIValueError("编码数据长度不足：缺少完整的 32 字节字")
    return data[pos:pos + _WORD]


def _decode_elementary(t: ElementaryType, data: bytes, pos: int, bound: int):
    """解码基础类型实体，返回 ``(值, 终点位置)``。"""
    kind = t.kind
    if kind == "string" or (kind == "bytes" and t.byte_size is None):
        length = int.from_bytes(_read_word(data, pos, bound), "big", signed=False)
        payload_start = pos + _WORD
        padded_length = ((length + _WORD - 1) // _WORD) * _WORD
        end = payload_start + padded_length
        if end > bound:
            raise ABIValueError("动态数据长度超出编码边界")
        payload_end = payload_start + length
        if data[payload_end:end] != b"\x00" * (end - payload_end):
            raise ABIValueError("动态数据尾部填充非零，编码不规范")
        payload = data[payload_start:payload_end]
        if kind == "string":
            try:
                value = payload.decode("utf-8")
            except UnicodeDecodeError as exc:
                raise ABIValueError(f"非法 UTF-8 字符串：{exc}") from exc
        else:
            value = payload
        return value, end

    word = _read_word(data, pos, bound)
    end = pos + _WORD
    if kind == "uint":
        value = int.from_bytes(word, "big", signed=False)
        if value >= 1 << t.bit_size:
            raise ABIValueError(f"uint{t.bit_size} 解码值越界：{value}")
        return value, end
    if kind == "int":
        value = int.from_bytes(word, "big", signed=True)
        bits = t.bit_size
        low = -(1 << (bits - 1))
        high = (1 << (bits - 1)) - 1
        if not low <= value <= high:
            raise ABIValueError(f"int{bits} 解码值超出补码范围 [{low}, {high}]：{value}")
        return value, end
    if kind == "address":
        if word[:12] != b"\x00" * 12:
            raise ABIValueError("address 高位填充非零，超出 20 字节范围")
        return "0x" + word[12:].hex(), end
    if kind == "bool":
        if word == b"\x00" * _WORD:
            return False, end
        if word == b"\x00" * (_WORD - 1) + b"\x01":
            return True, end
        raise ABIValueError("非法布尔字：既非全 0 也非末尾字节为 1")
    # bytesM
    if word[t.byte_size:] != b"\x00" * (_WORD - t.byte_size):
        raise ABIValueError(f"bytes{t.byte_size} 尾部填充非零，编码不规范")
    return word[:t.byte_size], end


def _decode_block(
    member_types: list[ABIType], data: bytes, base: int, bound: int
):
    """解码一个 head/tail 块，返回 ``(按声明顺序的值列表, 块终点)``。

    动态成员的偏移必须恰好指向前一动态实体的终点（紧密排列），否则
    视为非法编码。
    """
    head_length = 0
    for member_type in member_types:
        head_length += _head_slot(member_type)
    head_end = base + head_length
    if head_end > bound:
        raise ABIValueError("编码数据长度不足：块 head 越界")

    values = [None] * len(member_types)
    cursor = head_end
    head_pos = base
    for index, member_type in enumerate(member_types):
        if _is_dynamic(member_type):
            offset = int.from_bytes(
                _read_word(data, head_pos, bound), "big", signed=False
            )
            target = base + offset
            if target != cursor:
                raise ABIValueError(
                    f"动态偏移非法：成员 {index} 应指向 {cursor}，实际指向 {target}"
                )
            values[index], cursor = _decode(member_type, data, target, bound)
        else:
            values[index], end = _decode(member_type, data, head_pos, bound)
            if end != head_pos + _static_size(member_type):
                raise ABIValueError("静态成员尺寸与声明不一致")
        head_pos += _head_slot(member_type)
    return values, cursor


def _decode(abi_type: ABIType, data: bytes, pos: int, bound: int):
    """从 ``pos`` 解码一个实体，返回 ``(值, 终点位置)``，不越过 bound。"""
    if isinstance(abi_type, ElementaryType):
        return _decode_elementary(abi_type, data, pos, bound)
    if isinstance(abi_type, ArrayType):
        element_type = abi_type.element_type
        if abi_type.length is None:
            count = int.from_bytes(_read_word(data, pos, bound), "big", signed=False)
            base = pos + _WORD
            if base > bound:
                raise ABIValueError("编码数据长度不足：动态数组缺少元素块")
        else:
            count = abi_type.length
            base = pos
        # 先按 head 尺寸拦截伪造的超大长度，避免成员列表内存放大。
        slot = _head_slot(element_type)
        remaining = bound - base
        if slot:
            if count > remaining // slot:
                raise ABIValueError("数组元素块越界：长度与数据不符")
            member_types = [element_type] * count
        elif count:
            # 零尺寸静态元素（如 ()）：实体不占字节，无法用剩余数据约束
            # 长度；仅需防止离谱的乘法分配。
            try:
                member_types = [element_type] * count
            except (MemoryError, OverflowError) as exc:
                raise ABIValueError("数组长度过大，超出可解码范围") from exc
        else:
            member_types = []
        values, end = _decode_block(member_types, data, base, bound)
        return values, end
    if isinstance(abi_type, TupleType):
        values, end = _decode_block(list(abi_type.components), data, pos, bound)
        return tuple(values), end
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


# ---- 公开入口 ------------------------------------------------------------


def encode_abi_value(abi_type: ABIType, value) -> bytes:
    """按 ``abi_type`` 把 Python 值编码为完整 ABI 编码 bytes。

    值与类型不匹配或类型对象不适用时抛出 :class:`abi_kit.ABIValueError`。
    """
    if not isinstance(abi_type, ABIType):
        raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")
    return _encode(abi_type, value)


def decode_abi_value(abi_type: ABIType, data: bytes):
    """把完整 ABI 编码 bytes 解码回 Python 值。

    要求 ``data`` 恰好容纳一个值：长度不足、偏移越界、尾部残留、
    定长数组长度不符、非法布尔字、非法 UTF-8 或越界数值均抛出
    :class:`abi_kit.ABIValueError`。
    """
    if not isinstance(abi_type, ABIType):
        raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")
    if not isinstance(data, bytes):
        raise ABIValueError(f"编码数据必须是 bytes，得到 {type(data).__name__}")

    bound = len(data)
    value, end = _decode(abi_type, data, 0, bound)
    if end != bound:
        raise ABIValueError(
            f"尾部残留 {bound - end} 字节：编码未被完整消费"
        )
    return value

