    def test_identifier_rules(self):
        for name in ("a", "_a", "$a", "A1_b$", "x9"):
            event = parse_event_abi({"type": "event", "name": name, "inputs": []})
            self.assertEqual(event.name, name)

    def test_declaration_types_preserved(self):
        event = parse_event_abi(
