import ast
src = open('tests/test_event.py').read()
tree = ast.parse(src)
imported = set()
for node in ast.walk(tree):
    if isinstance(node, ast.ImportFrom):
        for a in node.names:
            imported.add(a.asname or a.name)
used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
print("unused imports:", sorted(i for i in imported if i not in used))
EOF
